function planDispatch(meta, response, input, cfg, nowISO, executionId) {
  const now=new Date(nowISO), ts=now.getTime();
  const local=new Intl.DateTimeFormat('en-CA',{timeZone:cfg.timezone,year:'numeric',month:'2-digit',day:'2-digit'}).format(now);
  const timeParts=new Intl.DateTimeFormat('en-GB',{timeZone:cfg.timezone,hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(now);
  const minuteOfDay=Number(timeParts.find(p=>p.type==='hour').value)*60+Number(timeParts.find(p=>p.type==='minute').value);
