    const overdue=busy.filter(t=>t.status==='awaiting_review'&&t.review_deadline&&Date.parse(t.review_deadline)+15*60000<ts);
    Object.assign(run,{accepted_count:done.length,rejected_count:members.filter(t=>t.status==='rejected').length,timed_out_count:members.filter(t=>t.status==='timed_out').length,blocked_count:blocked.length,skipped_count:members.filter(t=>t.status==='skipped').length,attempted_count:members.length,active_count:busy.length,waiting_count:busy.filter(t=>t.status==='awaiting_review').length,last_heartbeat_at:nowISO});
