      notices.push({text:'لم تبدأ دفعة '+local+' لأن دفعة '+run.batch_id+' ما زالت '+run.status,batch_id:batchId});
    }else{
      notices.push({text:'بدأت دفعة '+local+' — الهدف 10 مسودات مقبولة، بحد أقصى مقالين معًا.',batch_id:batchId});
      const available=topics.filter(t=>['','pending'].includes(String(t.status).trim().toLowerCase())&&!t.batch_id&&!t.wordpress_post_id&&!t.wordpress_url&&t.topic); available.sort((a,b)=>Number(a._row)-Number(b._row)||String(a.topic_id).localeCompare(String(b.topic_id),undefined,{numeric:true}));
      for(let i=0;i<Math.min(cfg.max_parallel,available.length);i++){
        const t=available[i],token='u'+revision+'_'+String(t.topic_id).replace(/[^A-Za-z0-9_]/g,'_')+'_'+i;
        Object.assign(t,{status:'queued',batch_id:batchId,reservation_token:token,reserved_at:nowISO,lease_until:new Date(ts+60*60000).toISOString(),attempt_count:1,stage:'queued',last_error:'',failure_class:'',heartbeat_at:nowISO});
        write(cfg.topics_gid,t._row,cfg.topic_headers,t);jobs.push({batch_id:batchId,topic_id:String(t.topic_id),reservation_token:token,attempt:1});
      }
      fresh.attempted_count=jobs.filter(j=>j.batch_id===batchId).length;fresh.active_count=fresh.attempted_count;
    }
    fresh.notification=notices[notices.length-1]?.text||'';
    write(cfg.runs_gid,row,cfg.run_headers,fresh);
  }
  for(const r of runs)if(r.notification&&!r.notification_sent&&!notices.some(n=>n.batch_id===r.batch_id))notices.push({text:r.notification,batch_id:r.batch_id});
